const $ = (s, root=document) => root.querySelector(s);
const state = { token: localStorage.getItem('mobrix_token'), user: null, company: null, page: 'dashboard', cache: {}, classic: { tab:'orcamento', items:[], pieces:[], client:'', markup:0 } };
try { state.classic = { ...state.classic, ...JSON.parse(localStorage.getItem('mobrix_classic') || '{}') }; } catch {}
function saveClassic(){ try { localStorage.setItem('mobrix_classic', JSON.stringify(state.classic)); } catch {} }
const pageMeta = {
  dashboard:['PAINEL DE CONTROLE','Visão geral'],
  projects:['GESTÃO DE PROJETOS','Projetos e móveis'],
  orders:['CHÃO DE FÁBRICA','Ordens de produção'],
  engineering:['ENGENHARIA','Ficha técnica e peças'],
  offcuts:['APROVEITAMENTO','Banco de retalhos'],
  productivity:['INDICADORES INDUSTRIAIS','Produtividade e horas'],
  classic:['FERRAMENTAS DE MARCENARIA','Ferramentas clássicas'],
  customers:['RELACIONAMENTO','Clientes'],
  materials:['CONTROLE DE MATERIAIS','Estoque e materiais'],
  finance:['CONTROLE FINANCEIRO','Financeiro'],
  settings:['PREFERÊNCIAS','Configurações']
};
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => Number(value || 0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date = value => value ? new Date(value+'T00:00:00').toLocaleDateString('pt-BR') : '—';
const statusLabel = s => ({orcamento:'Orçamento',aprovado:'Aprovado',producao:'Em produção',concluido:'Concluído',cancelado:'Cancelado',planejamento:'Planejamento',corte:'Corte',usinagem:'Usinagem',montagem:'Montagem',acabamento:'Acabamento',instalacao:'Instalação',pausado:'Pausado'})[s] || s || '—';
const pillClass = s => ['concluido','aprovado'].includes(s) ? 'green' : ['cancelado','atrasado'].includes(s) ? 'red' : ['orcamento','planejamento'].includes(s) ? 'orange' : '';
async function api(url, options={}) {
  const response = await fetch('/api'+url,{...options,headers:{'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{}),...(options.headers||{})}});
  const data = await response.json().catch(()=>({}));
  if (!response.ok) { if(response.status===401){logout(false)} throw new Error(data.error || 'Não foi possível concluir a operação.'); }
  return data;
}
function toast(message,error=false){const node=document.createElement('div');node.className='toast'+(error?' error':'');node.textContent=message;$('#toast-root').append(node);setTimeout(()=>node.remove(),3400)}
function showAuth(register=false){$('#auth-screen').classList.remove('hidden');$('#app').classList.add('hidden');$('#login-form').classList.toggle('hidden',register);$('#register-form').classList.toggle('hidden',!register);$('#auth-title').innerHTML=register?'Comece a organizar<br><span>sua produção.</span>':'Sua marcenaria,<br><span>sob controle.</span>';$('#auth-description').textContent=register?'Crie o ambiente da sua empresa no MOBRIX.':'Entre para acompanhar sua operação.';$('#auth-switch').innerHTML=register?'Já possui acesso? <button type="button" id="show-login">Fazer login</button>':'Ainda não tem acesso? <button type="button" id="show-register">Criar empresa</button>';$('#auth-error').textContent=''}
function showApp(){ $('#auth-screen').classList.add('hidden');$('#app').classList.remove('hidden');$('#user-name').textContent=state.user?.name||'Usuário';$('#user-role').textContent=state.user?.role==='admin'?'Administrador':'Equipe';$('#user-avatar').textContent=(state.user?.name||'M').slice(0,1).toUpperCase();$('#profile-shortcut').textContent=(state.user?.name||'M').slice(0,1).toUpperCase();$('#company-name').textContent=state.company?.name||'Minha empresa';$('#today').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'short',year:'numeric'}); }
function logout(notify=true){state.token=null;state.user=null;state.company=null;localStorage.removeItem('mobrix_token');showAuth();if(notify)toast('Você saiu da sua conta.')}
async function initialize(){if(!state.token){showAuth();return}try{const data=await api('/me');state.user=data.user;state.company=data.company;showApp();await navigate('dashboard')}catch{logout(false)}}
$('#auth-switch').addEventListener('click',e=>{if(e.target.id==='show-register')showAuth(true);if(e.target.id==='show-login')showAuth(false)});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);$('#auth-error').textContent='';try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.token=d.token;state.user=d.user;localStorage.setItem('mobrix_token',d.token);await initialize()}catch(err){$('#auth-error').textContent=err.message}});
$('#register-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);$('#auth-error').textContent='';try{const d=await api('/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});state.token=d.token;state.user=d.user;localStorage.setItem('mobrix_token',d.token);await initialize()}catch(err){$('#auth-error').textContent=err.message}});
$('#logout').addEventListener('click',()=>logout());$('#profile-shortcut').addEventListener('click',()=>navigate('settings'));$('#mobile-menu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#sidebar-overlay')?.classList.toggle('visible',open)});
$('.nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)navigate(b.dataset.page)});
async function navigate(page){if(page!=='classic'){if(furnitureViewer){furnitureViewer.destroy();furnitureViewer=null}if(importedModelViewer){importedModelViewer.destroy();importedModelViewer=null}}state.page=page;$('.nav-item.active')?.classList.remove('active');$('[data-page="'+page+'"]')?.classList.add('active');$('#page-kicker').textContent=pageMeta[page][0];$('#page-title').textContent=pageMeta[page][1];$('#sidebar').classList.remove('open');$('#sidebar-overlay')?.classList.remove('visible');$('#page-content').innerHTML='<div class="loading">Carregando dados...</div>';try{if(page==='dashboard')await renderDashboard();else if(page==='settings')renderSettings();else if(['engineering','offcuts','productivity'].includes(page))await renderIndustrial(page);else if(page==='classic')renderClassic();else await renderResource(page)}catch(e){$('#page-content').innerHTML='<div class="panel empty-state">'+esc(e.message)+'</div>'}}
async function renderDashboard(){const d=await api('/dashboard');$('#page-content').innerHTML=`
  <div class="welcome-row"><div><h2>Bom trabalho, ${esc((state.user?.name||'').split(' ')[0])}.</h2><p>Acompanhe os principais números da sua operação.</p></div><button class="btn btn-primary" data-action="new-project">＋ Novo projeto</button></div>
  <div class="stats-grid">
    <article class="stat-card"><div class="stat-head">Projetos ativos <span class="stat-icon">◇</span></div><div class="stat-value">${d.projects.active}</div><div class="stat-foot">${d.projects.total} projetos cadastrados</div></article>
    <article class="stat-card"><div class="stat-head">Ordens em andamento <span class="stat-icon">▤</span></div><div class="stat-value">${d.orders.active}</div><div class="stat-foot">${d.orders.total} ordens registradas</div></article>
    <article class="stat-card"><div class="stat-head">Valor em negociação <span class="stat-icon">＄</span></div><div class="stat-value">${money(d.projects.pipeline)}</div><div class="stat-foot">Valor de venda dos projetos ativos</div></article>
    <article class="stat-card"><div class="stat-head">Estoque crítico <span class="stat-icon">▧</span></div><div class="stat-value">${d.lowStock}</div><div class="stat-foot">Materiais no mínimo ou abaixo</div></article>
  </div>
  <div class="dashboard-grid">
    <section class="panel"><div class="panel-head"><div><h3>Projetos recentes</h3><p>Últimos projetos cadastrados</p></div><button class="text-link" data-page="projects">Ver todos →</button></div><div class="data-list">${d.recent.length?d.recent.map(p=>`<div class="data-row"><div class="data-main"><strong>${esc(p.title)}</strong><small>${esc(p.customer||'Cliente não definido')} · Entrega: ${date(p.deadline)}</small></div><span class="pill ${pillClass(p.status)}">${esc(statusLabel(p.status))}</span></div>`).join(''):'<div class="empty-state">Nenhum projeto cadastrado. Crie o primeiro para começar.</div>'}</div></section>
    <section class="panel"><div class="panel-head"><div><h3>Resumo financeiro</h3><p>Valores já marcados como pagos</p></div><button class="text-link" data-page="finance">Detalhes →</button></div><div class="data-row"><div class="data-main"><strong>Receitas recebidas</strong><small>Entradas confirmadas</small></div><strong class="kpi-positive">${money(d.finance.income)}</strong></div><div class="data-row"><div class="data-main"><strong>Despesas pagas</strong><small>Saídas confirmadas</small></div><strong>${money(d.finance.expenses)}</strong></div><div class="data-row"><div class="data-main"><strong>Resultado</strong><small>Receitas menos despesas</small></div><strong class="${Number(d.finance.income)-Number(d.finance.expenses)>=0?'kpi-positive':''}">${money(Number(d.finance.income)-Number(d.finance.expenses))}</strong></div><div class="empty-state">Registre receitas e despesas para acompanhar a saúde financeira.</div></section>
  </div>`;}
const configs={
 customers:{title:'Clientes',endpoint:'/customers',add:'Novo cliente',columns:[['name','Nome'],['phone','Telefone'],['email','E-mail']],fields:[['name','Nome','text',true],['phone','Telefone','text'],['email','E-mail','email'],['document','CPF/CNPJ','text'],['address','Endereço','text','full'],['notes','Observações','textarea','full']]},
 projects:{title:'Projetos e móveis',endpoint:'/projects',add:'Novo projeto',columns:[['title','Projeto'],['customer_name','Cliente'],['sale_price','Valor'],['deadline','Prazo'],['status','Status']],fields:[['title','Nome do projeto','text',true],['customer_id','Cliente','customer'],['description','Descrição','textarea','full'],['estimated_cost','Custo estimado','number'],['sale_price','Preço de venda','number'],['deadline','Prazo de entrega','date'],['status','Etapa','select:orcamento|aprovado|producao|concluido|cancelado']]},
 orders:{title:'Ordens de produção',endpoint:'/orders',add:'Nova ordem',columns:[['code','Ordem'],['project_title','Projeto'],['stage','Etapa'],['priority','Prioridade'],['due_date','Entrega']],fields:[['project_id','Projeto','project',true],['stage','Etapa','select:planejamento|corte|usinagem|montagem|acabamento|instalacao|concluido|pausado'],['priority','Prioridade','select:baixa|normal|alta|urgente'],['due_date','Prazo','date'],['notes','Observações','textarea','full']]},
 materials:{title:'Estoque e materiais',endpoint:'/materials',add:'Novo material',columns:[['name','Material'],['category','Categoria'],['quantity','Saldo'],['unit','Unidade'],['unit_cost','Custo unitário'],['stock_status','Situação']],fields:[['name','Material','text',true],['category','Categoria','text'],['unit','Unidade','text'],['quantity','Quantidade inicial','number'],['minimum_quantity','Estoque mínimo','number'],['unit_cost','Custo unitário','number'],['supplier','Fornecedor','text']]},
 finance:{title:'Financeiro',endpoint:'/finance',add:'Lançamento',columns:[['description','Descrição'],['transaction_type','Tipo'],['amount','Valor'],['due_date','Vencimento'],['paid_at','Situação']],fields:[['description','Descrição','text',true],['transaction_type','Tipo','select:receita|despesa',true],['amount','Valor (R$)','number',true],['due_date','Vencimento','date'],['project_id','Projeto','project'],['paid_at','Pago em (preencha para marcar como pago)','date']]}
};
async function renderResource(page){const cfg=configs[page];let rows=await api(cfg.endpoint);if(page==='projects'){const customers=await api('/customers');rows=rows.map(r=>({...r,customer_name:customers.find(c=>c.id===r.customer_id)?.name||'—'}));}if(page==='orders'){const projects=await api('/projects');rows=rows.map(r=>({...r,project_title:projects.find(p=>p.id===r.project_id)?.title||'—'}));}if(page==='materials')rows=rows.map(r=>({...r,stock_status:Number(r.quantity)<=Number(r.minimum_quantity)?'Crítico':'Normal'}));state.cache[page]=rows;drawTable(page,rows)}
function cellValue(row,key){let v=row[key];if(key==='sale_price'||key==='estimated_cost'||key==='unit_cost'||key==='amount')return money(v);if(['deadline','due_date','paid_at'].includes(key))return key==='paid_at'?(v?'Pago':'Pendente'):date(v);if(key==='status'||key==='stage')return '<span class="pill '+pillClass(v)+'">'+esc(statusLabel(v))+'</span>';if(key==='transaction_type')return v==='receita'?'Receita':'Despesa';if(key==='stock_status')return '<span class="pill '+(v==='Crítico'?'red':'green')+'">'+v+'</span>';if(key==='priority')return esc(({urgente:'Urgente',alta:'Alta',normal:'Normal',baixa:'Baixa'})[v]||v);return esc(v??'—')}
function drawTable(page,rows){
  const cfg=configs[page],stages=['planejamento','corte','usinagem','montagem','acabamento','instalacao','concluido'];
  const nextStage=stage=>{const i=stages.indexOf(stage);return i<0?null:stages[Math.min(i+1,stages.length-1)]};
  const renderRows=list=>list.length?list.map(r=>'<tr>'+cfg.columns.map(c=>'<td>'+cellValue(r,c[0])+'</td>').join('')+(page==='orders'?'<td>'+(r.stage==='concluido'?'<span class="pill green">Finalizada</span>':'<button class="btn btn-secondary" data-action="advance-order" data-id="'+esc(r.id)+'" data-stage="'+esc(nextStage(r.stage)||'planejamento')+'">Avançar etapa</button>')+'</td>':'')+'</tr>').join(''):'<tr><td colspan="'+(cfg.columns.length+(page==='orders'?1:0))+'" class="table-empty">Nenhum registro encontrado.</td></tr>';
  $('#page-content').innerHTML='<div class="page-toolbar"><div><h2>'+cfg.title+'</h2></div><div class="toolbar-actions"><input class="search-input" id="table-search" placeholder="Buscar registros..."><button class="btn btn-primary" data-action="new-'+page+'">＋ '+cfg.add+'</button></div></div><div class="table-panel"><div class="table-wrap"><table><thead><tr>'+cfg.columns.map(c=>'<th>'+c[1]+'</th>').join('')+(page==='orders'?'<th>Ação</th>':'')+'</tr></thead><tbody id="table-body">'+renderRows(rows)+'</tbody></table></div></div>';
  $('#table-search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();const filtered=rows.filter(r=>Object.values(r).some(v=>String(v??'').toLowerCase().includes(q)));$('#table-body').innerHTML=renderRows(filtered)});
}
async function openForm(page){const cfg=configs[page];let projects=[],customers=[];if(cfg.fields.some(f=>['project','customer'].includes(f[2]))){[projects,customers]=await Promise.all([api('/projects'),api('/customers')])}const fields=cfg.fields.map(f=>{let [name,label,type,extra]=f;let cls=extra==='full'?'full':'';let required=extra===true?'required':'';let input='';if(type==='textarea')input='<textarea name="'+name+'" rows="3"></textarea>';else if(type==='customer'||type==='project'){const list=type==='customer'?customers:projects;input='<select name="'+name+'"><option value="">Selecione</option>'+list.map(x=>'<option value="'+x.id+'">'+esc(x.name||x.title)+'</option>').join('')+'</select>'}else if(type.startsWith('select:'))input='<select name="'+name+'" '+required+'>'+type.slice(7).split('|').map(v=>'<option value="'+v+'">'+esc(statusLabel(v))+'</option>').join('')+'</select>';else input='<input name="'+name+'" type="'+type+'" '+(type==='number'?'step="0.01" min="0"':'')+' '+required+'>';return '<label class="field '+cls+'">'+label+input+'</label>'}).join('');document.body.classList.add('modal-open');$('#modal-root').innerHTML='<div class="modal-backdrop"><form class="modal" id="record-form"><div class="modal-head"><h3>'+cfg.add+'</h3><button type="button" class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><div class="form-grid">'+fields+'</div></div><div class="modal-foot"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">Salvar registro</button></div></form></div>';$('#record-form').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));Object.keys(data).forEach(k=>{if(data[k]==='')delete data[k]});if(data.paid_at)data.paid_at=new Date(data.paid_at+'T12:00:00').toISOString();try{await api(cfg.endpoint,{method:'POST',body:JSON.stringify(data)});closeModal();toast('Registro salvo com sucesso.');await navigate(page)}catch(err){toast(err.message,true)}})}

async function renderIndustrial(page){
  if(page==='engineering'){
    const [parts,projects,materials]=await Promise.all([api('/engineering/parts'),api('/projects'),api('/materials')]);
    $('#page-content').innerHTML=`<div class="page-toolbar"><div><h2>Ficha técnica e lista de peças</h2><p class="muted">Dimensões em milímetros, material e sentido do veio.</p></div><button class="btn btn-primary" data-action="new-part">＋ Adicionar peça</button></div><div class="table-panel"><div class="table-wrap"><table><thead><tr><th>Peça</th><th>Projeto</th><th>Dimensões</th><th>Espessura</th><th>Qtd.</th><th>Veio</th><th></th></tr></thead><tbody>${parts.length?parts.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small class="muted"> ${esc(p.material_name||'Sem material')}</small></td><td>${esc(p.project_title)}</td><td>${p.length_mm} × ${p.width_mm} mm</td><td>${p.thickness_mm} mm</td><td>${p.quantity}</td><td>${esc(p.grain_direction)}</td><td><button class="btn btn-danger" data-action="delete-part" data-id="${p.id}">Excluir</button></td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">Nenhuma peça cadastrada.</td></tr>'}</tbody></table></div></div>`;
    $('#page-content').dataset.projects=JSON.stringify(projects.map(p=>({id:p.id,title:p.title})));
    $('#page-content').dataset.materials=JSON.stringify(materials.map(m=>({id:m.id,name:m.name})));
    return;
  }
  if(page==='offcuts'){
    const [items,materials]=await Promise.all([api('/offcuts'),api('/materials')]);
    const label={disponivel:'Disponível',reservado:'Reservado',consumido:'Consumido',descartado:'Descartado'};
    $('#page-content').innerHTML=`<div class="page-toolbar"><div><h2>Banco de retalhos</h2><p class="muted">Registre sobras identificadas para reaproveitamento.</p></div><button class="btn btn-primary" data-action="new-offcut">＋ Registrar retalho</button></div><div class="table-panel"><div class="table-wrap"><table><thead><tr><th>Identificação</th><th>Material</th><th>Dimensões</th><th>Espessura</th><th>Situação</th><th>Ação</th></tr></thead><tbody>${items.length?items.map(x=>`<tr><td><strong>${esc(x.label)}</strong></td><td>${esc(x.material_name||'—')}</td><td>${x.length_mm} × ${x.width_mm} mm</td><td>${x.thickness_mm} mm</td><td><span class="pill ${x.status==='disponivel'?'green':''}">${label[x.status]||x.status}</span></td><td><select data-offcut-status="${x.id}">${Object.entries(label).map(([k,v])=>`<option value="${k}" ${k===x.status?'selected':''}>${v}</option>`).join('')}</select></td></tr>`).join(''):'<tr><td colspan="6" class="table-empty">Nenhum retalho registrado.</td></tr>'}</tbody></table></div></div>`;
    $('#page-content').dataset.materials=JSON.stringify(materials.map(m=>({id:m.id,name:m.name})));
    return;
  }
  const [metrics,entries,projects]=await Promise.all([api('/production/metrics'),api('/time-entries'),api('/projects')]);
  const mins=Number(metrics.work.minutes||0);
  $('#page-content').innerHTML=`<div class="welcome-row"><div><h2>Produtividade da fábrica</h2><p>Apontamentos registrados no mês atual.</p></div><button class="btn btn-primary" data-action="new-time-entry">＋ Apontar horas</button></div><div class="stats-grid"><article class="stat-card"><div class="stat-head">Ordens atrasadas</div><div class="stat-value">${metrics.lateOrders}</div><div class="stat-foot">Exigem acompanhamento</div></article><article class="stat-card"><div class="stat-head">Horas apontadas</div><div class="stat-value">${(mins/60).toFixed(1)} h</div><div class="stat-foot">${metrics.work.entries} apontamentos no mês</div></article><article class="stat-card"><div class="stat-head">Retalhos disponíveis</div><div class="stat-value">${metrics.offcuts.available}</div><div class="stat-foot">${Number(metrics.offcuts.area_m2||0).toFixed(2)} m² registrados</div></article><article class="stat-card"><div class="stat-head">Ordens em produção</div><div class="stat-value">${metrics.stages.reduce((s,x)=>s+Number(x.total),0)}</div><div class="stat-foot">Distribuição por etapa abaixo</div></article></div><section class="panel"><div class="panel-head"><div><h3>Apontamentos recentes</h3><p>Tempo por colaborador e operação</p></div></div><div class="data-list">${entries.length?entries.slice(0,12).map(x=>`<div class="data-row"><div class="data-main"><strong>${esc(x.employee_name)} · ${esc(x.operation)}</strong><small>${esc(x.project_title)} · ${new Date(x.started_at).toLocaleString('pt-BR')}</small></div><strong>${x.duration_minutes==null?'Em aberto':(Number(x.duration_minutes)/60).toFixed(2)+' h'}</strong></div>`).join(''):'<div class="empty-state">Ainda não existem apontamentos de produção.</div>'}</div></section>`;
  $('#page-content').dataset.projects=JSON.stringify(projects.map(p=>({id:p.id,title:p.title})));
}
async function openIndustrialForm(kind){
  const root=$('#page-content');
  const projects=JSON.parse(root.dataset.projects||'[]'),materials=JSON.parse(root.dataset.materials||'[]');
  const select=(name,label,items,required=true)=>'<label class="field">'+label+'<select name="'+name+'" '+(required?'required':'')+'><option value="">Selecione</option>'+items.map(x=>'<option value="'+x.id+'">'+esc(x.title||x.name)+'</option>').join('')+'</select></label>';
  let title='',fields='';
  if(kind==='part'){title='Adicionar peça à ficha técnica';fields=select('project_id','Projeto',projects)+select('material_id','Material',materials,false)+'<label class="field">Nome da peça<input name="name" required></label><label class="field">Comprimento (mm)<input name="length_mm" type="number" min="1" step="1" required></label><label class="field">Largura (mm)<input name="width_mm" type="number" min="1" step="1" required></label><label class="field">Espessura (mm)<input name="thickness_mm" type="number" min="0.1" step="0.1" required></label><label class="field">Quantidade<input name="quantity" type="number" min="1" step="1" value="1" required></label><label class="field">Sentido do veio<select name="grain_direction"><option value="livre">Livre</option><option value="comprimento">Comprimento</option><option value="largura">Largura</option></select></label><label class="field full">Fita de borda / observações<input name="edge_banding"></label>'}
  if(kind==='offcut'){title='Registrar retalho';fields=select('material_id','Material',materials,false)+'<label class="field">Identificação<input name="label" required placeholder="Ex.: MDF Branco 18 mm - R01"></label><label class="field">Comprimento (mm)<input name="length_mm" type="number" min="1" required></label><label class="field">Largura (mm)<input name="width_mm" type="number" min="1" required></label><label class="field">Espessura (mm)<input name="thickness_mm" type="number" min="0.1" step="0.1" required></label><label class="field">Sentido do veio<select name="grain_direction"><option value="livre">Livre</option><option value="comprimento">Comprimento</option><option value="largura">Largura</option></select></label>'}
  if(kind==='time'){title='Apontar tempo de produção';fields=select('project_id','Projeto',projects)+'<label class="field">Colaborador<input name="employee_name" required></label><label class="field">Operação<input name="operation" required placeholder="Corte, usinagem, montagem..."></label><label class="field">Início<input name="started_at" type="datetime-local" required></label><label class="field">Término<input name="ended_at" type="datetime-local"></label><label class="field full">Observações<textarea name="notes" rows="2"></textarea></label>'}
  document.body.classList.add('modal-open');$('#modal-root').innerHTML='<div class="modal-backdrop"><form class="modal" id="industrial-form"><div class="modal-head"><h3>'+title+'</h3><button type="button" class="modal-close" data-action="close-modal">×</button></div><div class="modal-body"><div class="form-grid">'+fields+'</div></div><div class="modal-foot"><button type="button" class="btn btn-quiet" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">Salvar</button></div></form></div>';
  $('#industrial-form').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));Object.keys(data).forEach(k=>{if(data[k]==='')delete data[k]});if(data.started_at)data.started_at=new Date(data.started_at).toISOString();if(data.ended_at)data.ended_at=new Date(data.ended_at).toISOString();const endpoint=kind==='part'?'/engineering/parts':kind==='offcut'?'/offcuts':'/time-entries';try{await api(endpoint,{method:'POST',body:JSON.stringify(data)});closeModal();toast('Registro salvo.');await navigate(state.page)}catch(err){toast(err.message,true)}});
}


